src/types.ts.content:
/**
 * Shared DTO contracts between the @api NestJS service and any consumer
 * (web frontend, admin backend, mobile, automation, ...).
 *
 * The shape mirrors the MikroORM entities in `apps/api/src/entities` so the
 * SDK never needs to keep parallel definitions in sync manually.
 */

export type Iso8601 = string;

export interface AuditFields {
  id: number;
  createdAt: Iso8601;
  updatedAt: Iso8601;
}

/** Một role gắn với user (nhiều role / union quyền). */
export interface UserRoleRef {
  code: string;
  name: string;
}

/** Role trả từ `/admin/auth/*` và các payload user của API HUB. */
export interface AuthRoleRef {
  id: number;
  name: string;
  displayName: string;
}

/** Admin user — `id` số tự tăng (`BaseEntity` API). */
export interface User extends AuditFields {
  email: string;
  fullName: string;
  phone?: string | null;
  address?: string | null;
  citizenId?: string | null;
  avatar?: string | null;
  roles: UserRoleRef[];
  isActive: boolean;
  /** Thùng rác admin — optional vì API danh sách chính không trả bản ghi đã xóa. */
  deletedAt?: Iso8601 | null;
}

/**
 * Payload xác thực của API HUB.
 * Khác với `User` admin-list: dùng `name`, `image`, role `{ id, name, displayName }`.
 */
export interface AuthUser {
  id: number;
  email: string;
  name: string | null;
  image: string | null;
  permissions: string[];
  roles: AuthRoleRef[];
  phone?: string | null;
  address?: string | null;
  updatedAt?: Iso8601;
}

export interface UserCredentials {
  email: string;
  password: string;
}

/** Payload giỏ hàng lưu trên user (đồng bộ với localStorage storefront). */
export interface UserCartPayload {
  lines: Array<Record<string, unknown>>;
}

export type CreateUserInput = Omit<User, keyof AuditFields | 'roles'> & {
  password: string;
  /** Gán role theo mã (vd: admin, customer); thay thế toàn bộ khi update. */
  roleCodes?: string[];
};

export type UpdateUserInput = Partial<CreateUserInput>;

/** Cập nhật hồ sơ (PUT /users/:id/profile) — không đổi email/mật khẩu/role. */
export type UpdateProfileInput = {
  fullName?: string;
  phone?: string;
  address?: string;
  avatar?: string | null;
};

export type ChangePasswordInput = {
  currentPassword: string;
  newPassword: string;
};

export type QuantityCountMode = 'sell_unit' | 'base_unit';
export type QuantityScope = 'line' | 'product';

export interface QuantityCondition {
  scope?: QuantityScope;
  minQty?: number;
  maxQty?: number;
  exactQty?: number;
  stepQty?: number;
  countMode?: QuantityCountMode;
}

export interface ProductPriceTier {
  minQty: number;
  unitPrice: number;
  label?: string;
}

export interface ProductGiftRule {
  id: string;
  label: string;
  trigger: QuantityCondition;
  gift: {
    name: string;
    sku?: string;
    productId?: number;
    qty: number;
    image?: string;
    qtyMultiplier?: 'once' | 'per_min_qty' | 'per_step';
  };
  applyPer?: 'order' | 'line';
}

export interface ProductUnitType {
  type: string;
  label: string;
  sku?: string;
  wholesalePrice: number | null;
  retailPrice: number;
  minWholesaleQty: number;
  qtyPerUnit: number;
  stock?: number;
  images?: string[];
  priceTiers?: ProductPriceTier[];
  giftRules?: ProductGiftRule[];
  isDefault?: boolean;
  isActive?: boolean;
}

/** Tham số lọc GET /products (admin / storefront có thể dùng từng phần). */
export interface ProductListParams {
  /** Tương đương ?active=true (chỉ còn bán) — ưu tiên khi không gửi isActive cụ thể. */
  activeOnly?: boolean;
  category?: string;
  brand?: string;
  /** SP không có brand (null / rỗng). */
  brandEmpty?: boolean;
  isActive?: boolean;
  /** Tìm theo SKU, tên, slug danh mục, brand (LIKE, không phân biệt hoa thường tùm DB). */
  q?: string;
  stock?: number;
  retailPrice?: number;
  /** Mức tồn: ok ≥50, low 1–49, out ≤0 (khớp admin computeStatus). */
  stockBand?: "ok" | "low" | "out";
  /** Lọc theo đơn vị tính (`unitTypes[].type` hoặc `unit`). */
  unitType?: string;
  /** Kiểu mua: có giá khuyến mãi (wholesale) / chỉ giá ban đầu (retail). */
  purchaseMode?: "si" | "le";
  /** Cùng `limit` → API trả `{ items, total }` thay vì mảng. */
  page?: number;
  limit?: number;
}

export interface Product extends AuditFields {
  sku: string;
  name: string;
  description?: string | null;
  category: string;
  brand?: string | null;
  origin?: string | null;
  basePrice: number;
  wholesalePrice: number;
  retailPrice: number;
  stock: number;
  unit: string;
  unitTypes?: ProductUnitType[] | null;
  images?: string[] | null;
  coupons?: string[] | null;
  /** Ghi chú quà / KM cho shipper (kho), ví dụ điều kiện tặng kèm. */
  fulfillmentNote?: string | null;
  isActive: boolean;
  /** Có giá trị khi sản phẩm đang trong thùng rác (xóa tạm). */
  deletedAt?: Iso8601 | null;
}

/** Kết quả phân trang từ GET /products?page=&limit= */
export interface ProductPagedResponse {
  items: Product[];
  total: number;
}

export type CreateProductInput = Omit<Product, keyof AuditFields>;
export type UpdateProductInput = Partial<CreateProductInput>;

export interface ChildCategory {
  id: number;
  name: string;
  slug: string;
  _count: { children: number };
  postCount: number;
}

export interface RelatedPost {
  id: number;
  title: string;
  slug: string;
  published: boolean;
  publishedAt: string | null;
  createdAt: string;
}

export interface Category extends AuditFields {
  name: string;
  slug: string;
  description?: string | null;
  icon?: string | null;
  sortOrder: number;
  isActive: boolean;
  parentId?: number | null;
  parentName?: string | null;
  _count?: { children: number };
  postCount?: number;
  deletedAt?: Iso8601 | null;
  children?: ChildCategory[];
  posts?: RelatedPost[];
}

export type CreateCategoryInput = {
  name: string;
  slug: string;
  description?: string | null;
  icon?: string | null;
  sortOrder?: number;
  isActive?: boolean;
  parentId?: number | null;
};
export type UpdateCategoryInput = Partial<CreateCategoryInput>;

export interface CategoryUsage {
  slug: string;
  productCount: number;
}

export type OrderStatus =
  | 'pending'
  | 'confirmed'
  | 'shipped'
  | 'delivered'
  | 'cancelled';

/** GET /orders/staff/status-counts — đếm đơn cho badge admin. */
export type StaffOrderStatusCounts = {
  ALL: number;
  pending: number;
  confirmed: number;
  shipped: number;
  delivered: number;
  cancelled: number;
};

export type PaymentMethod = 'cod';
export type PaymentStatus = 'unpaid' | 'paid';

export interface OrderItem {
  productId: number;
  sku: string;
  name: string;
  quantity: number;
  unitType: string;
  unitPrice: number;
  totalPrice: number;
  qtyPerUnit?: number;
  /**
   * URL ảnh tại thời điểm đặt.
   * Checkout nên copy file nội bộ sang `images/orders/{orderId}/` (UploadsService.snapshotOrderLineImages)
   * rồi lưu URL mới — đơn cũ không phụ thuộc catalog/ảnh sản phẩm sau này.
   */
  image?: string;
  /** Bản chụp ghi chú quà kèm từ sản phẩm lúc đặt hàng. */
  giftNote?: string;
  /** Giá ban đầu (retail) theo đơn vị tại thời điểm đặt — không đổi khi catalog cập nhật. */
  listUnitPrice?: number;
  /** Nhãn đơn vị tại thời điểm đặt. */
  unitLabel?: string;
  /** SKU biến thể tại thời điểm đặt. */
  variantSku?: string;
}

export interface OrderGiftSnapshot {
  ruleId?: string;
  label: string;
  sku?: string;
  name: string;
  qty: number;
  image?: string;
  productId?: number;
  unitType?: string;
}

/** User được gán làm shipper cho đơn (populate từ API). */
export type AssignedShipperRef = Pick<User, 'id' | 'fullName' | 'email'>;

export interface Order extends AuditFields {
  orderNumber: string;
  customer?: User | null;
  assignedShipper?: AssignedShipperRef | null;
  customerName: string;
  customerEmail: string;
  customerPhone?: string | null;
  shippingAddress?: string | null;
  items: OrderItem[];
  gifts?: OrderGiftSnapshot[];
  subtotal: number;
  discountAmount: number;
  shippingFee: number;
  totalAmount: number;
  status: OrderStatus;
  couponCode?: string | null;
  notes?: string | null;
  paymentMethod: PaymentMethod;
  paymentStatus: PaymentStatus;
  isPaid: boolean;
  shippedBy?: string | null;
  shippedAt?: Iso8601 | null;
  deliveredBy?: string | null;
  deliveredAt?: Iso8601 | null;
  cancelledAt?: Iso8601 | null;
  deletedAt?: Iso8601 | null;
}

/** Dòng giỏ lưu server — không có `stock` (client sync từ catalog). */
export interface CustomerCartLine {
  productId: number;
  sku: string;
  name: string;
  image?: string;
  category: string;
  unitType: string;
  unitLabel: string;
  unitPrice: number;
  listUnitPrice: number;
  promoUnitPrice: number | null;
  minPromoQty: number;
  qtyPerUnit: number;
  quantity: number;
  isWholesale: boolean;
  fulfillmentNote?: string | null;
  giftRules?: ProductGiftRule[];
}

export interface CustomerCartPayload {
  lines: CustomerCartLine[];
  appliedPromoCode: string | null;
}

export interface CustomerCartResponse extends CustomerCartPayload {
  updatedAt: string;
}

/**
 * Item storefront gửi lên; server gộp trùng (cùng product + đơn vị), tính giá
 * theo catalog tại thời điểm đặt và lưu bản chụp vào `Order.items` (không đổi sau này).
 */
export interface CreateOrderItemInput {
  productId: number;
  quantity: number;
  unitType: string;
}

export type PromoDiscountKind = 'fixed' | 'percent';

/** Bản ghi mã KM toàn đơn (admin). */
export interface PromoCode extends AuditFields {
  code: string;
  label: string;
  discountKind: PromoDiscountKind;
  discountFixed: number;
  discountPercent: number;
  discountCapVnd: number | null;
  minOrderSubtotal: number;
  isActive: boolean;
  validFrom: Iso8601 | null;
  validUntil: Iso8601 | null;
  usageLimit: number | null;
  usageCount: number;
}

export interface CreatePromoCodeInput {
  code: string;
  label: string;
  discountKind: PromoDiscountKind;
  discountFixed: number;
  discountPercent: number;
  discountCapVnd?: number | null;
  minOrderSubtotal: number;
  isActive?: boolean;
  validFrom?: string | null;
  validUntil?: string | null;
  usageLimit?: number | null;
}

export type UpdatePromoCodeInput = Partial<
  Omit<CreatePromoCodeInput, 'code'>
>;

export interface CreateOrderInput {
  customerId?: string | null;
  customerName: string;
  customerEmail: string;
  customerPhone?: string;
  shippingAddress?: string;
  notes?: string;
  couponCode?: string;
  paymentMethod?: PaymentMethod;
  items: CreateOrderItemInput[];
}
export type UpdateOrderInput = Partial<Omit<Order, keyof AuditFields>>;

export interface HealthStatus {
  status: 'ok';
  service: string;
  uptime: number;
  timestamp: Iso8601;
}

/** GET /rbac/permissions */
export interface RbacPermission {
  id: number;
  code: string;
  name: string;
  description: string | null;
}

/** GET /rbac/roles — mỗi role kèm danh sách mã quyền (đã sort). */
export interface RbacRole {
  id: number;
  code: string;
  name: string;
  description: string | null;
  permissions: string[];
}

/** PageContent — hướng dẫn sử dụng / nội dung trang động */
export interface PageContentStep {
  order: number;
  title: string;
  description: string;
  imageUrl?: string | null;
}

export interface PageContent extends AuditFields {
  pageKey: string;
  sectionKey: string;
  isVisible: boolean;
  content: {
    title?: string | null;
    description?: string | null;
    order?: number;
    steps?: PageContentStep[];
  };
  deletedAt?: Iso8601 | null;
}

export type CreatePageContentInput = {
  pageKey: string;
  sectionKey: string;
  isVisible?: boolean;
  content?: {
    title?: string | null;
    description?: string | null;
    order?: number;
    steps?: PageContentStep[];
  };
};

export type UpdatePageContentInput = Partial<Omit<CreatePageContentInput, 'pageKey' | 'sectionKey'>>;

/** Alias cho Guides (huong-dan-su-dung) */
export type GuideStep = PageContentStep;
export type GuideGroup = PageContent;
export type CreateGuideInput = CreatePageContentInput;
export type UpdateGuideInput = UpdatePageContentInput;

